use vstd::prelude::*;

verus! {

fn broadcast_arrays(a: Vec<i8>, b: Vec<i8>) -> (out: (Vec<i8>, Vec<i8>))
    requires
        a.len() > 0,
        b.len() > 0,
        a.len() == b.len() || a.len() == 1 || b.len() == 1,
    ensures
        out.0.len() == if a.len() >= b.len() { a.len() } else { b.len() },
        out.1.len() == if a.len() >= b.len() { a.len() } else { b.len() },

        // If not expanded, output equals the original vector.
        a.len() == (if a.len() >= b.len() { a.len() } else { b.len() }) ==> out.0@ == a@,
        b.len() == (if a.len() >= b.len() { a.len() } else { b.len() }) ==> out.1@ == b@,

        // If expanded from length 1, it is a repetition of the first element.
        a.len() != (if a.len() >= b.len() { a.len() } else { b.len() }) ==>
            (forall|i: int|
                0 <= i < out.0.len() ==> out.0@[i] == a@[0]),
        b.len() != (if a.len() >= b.len() { a.len() } else { b.len() }) ==>
            (forall|i: int|
                0 <= i < out.1.len() ==> out.1@[i] == b@[0]),
{
    assert!(!a.is_empty() && !b.is_empty(), "inputs must be non-empty");

    let m = a.len();
    let n = b.len();
    assert!(
        m == n || m == 1 || n == 1,
        "inputs must be compatible: same length or one has length 1"
    );

    let out_len = m.max(n);

    // Facts about max used by later reasoning.
    assert(out_len == if m >= n { m } else { n });

    let out_a: Vec<i8> = if m == out_len {
        a
    } else {
        // Here m != out_len; given compatibility and non-emptiness, m must be 1.
        assert(m == 1);
        vec![a[0]; out_len]
    };

    let out_b: Vec<i8> = if n == out_len {
        b
    } else {
        assert(n == 1);
        vec![b[0]; out_len]
    };

    (out_a, out_b)
}

} // verus!

